/* ============================================ */
/* FITNESS FIRST - PREMIUM FITNESS STYLING */
/* ============================================ */

@import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800;900&family=Inter:wght@300;400;500;600;700&display=swap');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* These styles get applied automatically */
.fitness-review-card {
  background: rgba(26, 26, 26, 0.9) !important;
  border: 2px solid rgba(229, 9, 20, 0.3) !important;
  color: #FFFFFF !important;
}

.fitness-rating-star {
  color: #E50914 !important;
}

.fitness-review-header {
  font-family: 'Montserrat', sans-serif !important;
}

/* ============================================ */
/* PROJECT GRID SPECIFIC STYLING - Fitness Classes Cards */
/* ============================================ */

/* Override ALL project grid cards */
.project-grid-item,
.class-card,
.item-card,
.grid-item,
.project-card,
[class*="grid-item"],
[class*="class-card"],
[class*="item-card"] {
  background: rgba(26, 26, 26, 0.9) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  border: 2px solid rgba(229, 9, 20, 0.3) !important;
  border-radius: 16px !important;
  color: #FFFFFF !important;
  overflow: hidden !important;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1) !important;
}

.project-grid-item:hover,
.class-card:hover,
.item-card:hover {
  transform: translateY(-10px) scale(1.02) !important;
  box-shadow: 0 20px 40px rgba(229, 9, 20, 0.3) !important;
  border: 2px solid rgba(229, 9, 20, 0.6) !important;
}

/* Project grid card content */
.project-grid-item h3,
.project-grid-item h4,
.class-card h3,
.class-card h4,
.item-card h3,
.item-card h4,
[class*="grid-item"] h3,
[class*="grid-item"] h4 {
  color: #FFFFFF !important;
  font-family: 'Montserrat', sans-serif !important;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5) !important;
}

.project-grid-item p,
.class-card p,
.item-card p,
[class*="grid-item"] p {
  color: rgba(255, 255, 255, 0.9) !important;
}

.project-grid-item .price,
.class-card .price,
.item-card .price,
[class*="grid-item"] .price {
  color: #E50914 !important;
  font-weight: 700 !important;
}

/* Project grid container */
.project-grid-container {
  background: transparent !important;
  padding: 20px 0 !important;
}

/* ============================================ */
/* CUSTOMER REVIEWS SPECIFIC STYLING */
/* ============================================ */

/* Override ALL customer review cards */
.customer-review-card,
.review-card,
.testimonial-card,
[class*="review-card"],
[class*="testimonial-card"] {
  background: rgba(26, 26, 26, 0.9) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  border: 2px solid rgba(0, 114, 206, 0.3) !important;
  border-radius: 16px !important;
  color: #FFFFFF !important;
  padding: 30px !important;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1) !important;
}

.customer-review-card:hover,
.review-card:hover,
.testimonial-card:hover {
  transform: translateY(-5px) !important;
  box-shadow: 0 15px 30px rgba(0, 114, 206, 0.3) !important;
  border: 2px solid rgba(0, 114, 206, 0.6) !important;
}

/* Review card content */
.customer-review-card h4,
.review-card h4,
.testimonial-card h4,
[class*="review-card"] h4 {
  color: #FFFFFF !important;
  font-family: 'Montserrat', sans-serif !important;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5) !important;
}

.customer-review-card p,
.review-card p,
.testimonial-card p,
[class*="review-card"] p {
  color: rgba(255, 255, 255, 0.9) !important;
  line-height: 1.6 !important;
}

.customer-review-card .rating,
.review-card .rating,
.testimonial-card .rating,
[class*="review-card"] .rating {
  color: #E50914 !important;
}

/* Review section container */
.reviews-section,
.customer-reviews-section,
[class*="reviews-section"] {
  background: transparent !important;
}

/* Review summary */
.review-summary,
.rating-summary,
[class*="summary"] {
  background: rgba(26, 26, 26, 0.9) !important;
  border: 2px solid rgba(229, 9, 20, 0.3) !important;
  border-radius: 16px !important;
  color: #FFFFFF !important;
  padding: 25px !important;
}

.review-summary h3,
.rating-summary h3,
[class*="summary"] h3 {
  color: #FFFFFF !important;
  font-family: 'Montserrat', sans-serif !important;
}

/* Write review button */
.write-review-btn,
[class*="write-review"] {
  background: linear-gradient(135deg, #E50914 0%, #FF4444 100%) !important;
  color: #FFFFFF !important;
  border: none !important;
  border-radius: 25px !important;
  padding: 12px 30px !important;
  font-weight: 600 !important;
  transition: all 0.3s ease !important;
}

.write-review-btn:hover,
[class*="write-review"]:hover {
  transform: translateY(-3px) !important;
  box-shadow: 0 10px 20px rgba(229, 9, 20, 0.5) !important;
}

/* ============================================ */
/* BASE STYLES - Fitness Theme */
/* ============================================ */
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  background: linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 100%) !important;
  background-attachment: fixed !important;
  color: #FFFFFF !important;
  min-height: 100vh;
  transition: background 0.6s ease, color 0.6s ease;
  overflow-x: hidden;
}

/* ============================================ */
/* DARK MODE - Fitness Gym Vibes */
/* ============================================ */
body.dark-mode {
  background: linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 70%, #0a0a0a 100%) !important;
  background-attachment: fixed !important;
  color: #FFFFFF !important;
}

/* Navbar links in dark mode */
body.dark-mode nav a,
body.dark-mode nav button {
  color: #FFFFFF !important;
  transition: all 0.2s ease;
}

body.dark-mode nav a:hover,
body.dark-mode nav button:hover {
  color: #E50914 !important;
  background: rgba(229, 9, 20, 0.1) !important;
}

/* Glass card styling */
.glass-card {
  background: rgba(26, 26, 26, 0.9) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border: 2px solid rgba(229, 9, 20, 0.3) !important;
  box-shadow: 0 8px 32px 0 rgba(229, 9, 20, 0.25) !important;
  color: #FFFFFF !important;
}

body.dark-mode .glass-card {
  background: rgba(20, 20, 20, 0.95) !important;
  border: 2px solid rgba(0, 114, 206, 0.3) !important;
  color: #FFFFFF !important;
}

/* Card text visibility */
.glass-card h1,
.glass-card h2,
.glass-card h3,
.glass-card p,
.glass-card span {
  color: #FFFFFF !important;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5) !important;
}

/* Navbar styling */
body nav,
body header {
  background: rgba(26, 26, 26, 0.95) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
  border-bottom: 2px solid rgba(229, 9, 20, 0.3) !important;
  color: #FFFFFF !important;
}

body.dark-mode nav,
body.dark-mode header {
  background: rgba(20, 20, 20, 0.95) !important;
  border-bottom: 2px solid rgba(0, 114, 206, 0.3) !important;
}

body nav a,
body header a,
body nav button,
body header button {
  color: #FFFFFF !important;
  font-weight: 500 !important;
}

/* Button styling */
.primary-btn {
  background: linear-gradient(135deg, #E50914 0%, #FF4444 100%) !important;
  color: #FFFFFF !important;
  border: none !important;
  border-radius: 25px !important;
  padding: 12px 30px !important;
  font-weight: 600 !important;
  transition: all 0.3s ease !important;
}

.primary-btn:hover {
  transform: translateY(-3px) !important;
  box-shadow: 0 10px 20px rgba(229, 9, 20, 0.5) !important;
}

/* Features cards */
.feature-card {
  background: rgba(26, 26, 26, 0.9) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  border: 2px solid rgba(229, 9, 20, 0.3) !important;
  border-radius: 16px !important;
  padding: 30px !important;
  color: #FFFFFF !important;
  transition: all 0.3s ease !important;
}

.feature-card:hover {
  transform: translateY(-10px) !important;
  box-shadow: 0 20px 40px rgba(229, 9, 20, 0.3) !important;
}

/* Stats section styling */
.stats-card {
  background: rgba(26, 26, 26, 0.9) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  border: 2px solid rgba(0, 114, 206, 0.3) !important;
  color: #FFFFFF !important;
  border-radius: 16px !important;
  padding: 30px !important;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5) !important;
}

/* Feature cards dark background */
.feature-content-card {
  background: rgba(26, 26, 26, 0.9) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  border: 2px solid rgba(229, 9, 20, 0.3) !important;
  color: #FFFFFF !important;
  border-radius: 16px !important;
  padding: 40px !important;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5) !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 10px;
}

::-webkit-scrollbar-track {
  background: rgba(229, 9, 20, 0.1);
  border-radius: 10px;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(135deg, #E50914 0%, #0072CE 100%);
  border-radius: 10px;
}

/* Animations */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(40px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes float {
  0%, 100% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(-20px);
  }
}

/* Form styling */
.form-container {
  background: rgba(26, 26, 26, 0.95) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  border: 2px solid rgba(229, 9, 20, 0.3) !important;
  color: #FFFFFF !important;
}

body.dark-mode .form-container {
  background: rgba(20, 20, 20, 0.95) !important;
  border: 2px solid rgba(0, 114, 206, 0.3) !important;
}

/* Input fields */
input, textarea, select {
  background: rgba(255, 255, 255, 0.1) !important;
  border: 1px solid rgba(229, 9, 20, 0.3) !important;
  color: #FFFFFF !important;
  padding: 12px 16px !important;
  border-radius: 10px !important;
}

input::placeholder,
textarea::placeholder {
  color: rgba(255, 255, 255, 0.6) !important;
}

/* Text colors for fitness vibe */
.fitness-red-text {
  color: #E50914 !important;
}

.fitness-blue-text {
  color: #0072CE !important;
}

.fitness-green-text {
  color: #00C851 !important;
}

.white-text {
  color: #FFFFFF !important;
}

/* Menu buttons */
.menu-button {
  background: rgba(229, 9, 20, 0.15) !important;
  border: 1px solid rgba(229, 9, 20, 0.2) !important;
  color: #FFFFFF !important;
  transition: all 0.3s ease !important;
}

.menu-button:hover {
  background: rgba(229, 9, 20, 0.25) !important;
  border-color: rgba(229, 9, 20, 0.4) !important;
  transform: translateX(5px);
}

.menu-button-active {
  background: rgba(229, 9, 20, 0.25) !important;
  border: 1px solid rgba(229, 9, 20, 0.4) !important;
  box-shadow: 0 4px 12px rgba(229, 9, 20, 0.25) !important;
}

/* Sidebar styling */
.sidebar-container {
  background: rgba(26, 26, 26, 0.9) !important;
  backdrop-filter: blur(20px) saturate(180%) !important;
  border-right: 2px solid rgba(229, 9, 20, 0.2) !important;
  color: #FFFFFF !important;
}

/* Responsive */
@media (max-width: 768px) {
  .hero-title {
    font-size: 2.5rem !important;
  }

  .hero-subtitle {
    font-size: 1.1rem !important;
  }

  nav {
    padding: 15px 20px !important;
  }

  .glass-card {
    padding: 25px !important;
  }

  .project-grid-item,
  .customer-review-card {
    margin-bottom: 20px !important;
  }
}

actions.checkExistingAuth:
console.log('🔍 Checking for existing authentication...');

  try {
    const response = await fetch('/api/enduser-auth/check-session?websiteSlug=fitness-first', {
      method: 'GET',
      credentials: 'include',
      headers: {
        'Content-Type': 'application/json',
        'x-website-slug': 'fitness-first'
      }
    });

    console.log('📡 Session check response status:', response.status);

    if (response.ok) {
      const data = await response.json();
      console.log('📦 Session data:', data);

      if (data.authenticated) {
        console.log('✅ User already authenticated:', data.user.email);

        context.handlers.setData('user', data.user);

        context.handlers.showNotification({
          type: 'toast',
          message: `Welcome back, ${data.user.firstName || data.user.email || 'Athlete'}! 💪`,
          background: '#0072CE',
          duration: 2000
        });

        setTimeout(() => {
          window.location.href = '/fitness-first/dashboard';
        }, 1000);

        return;
      } else {
        console.log('ℹ️ No active session');
      }
    } else {
      console.log('⚠️ Session check failed with status:', response.status);
    }

    console.log('ℹ️ Showing login form');

  } catch (error) {
    console.error('❌ Session check failed:', error);
  }

actions.api:
console.log("🔵 API action triggered");
  const apiKey = context.actionParams?.apiKey || context.actionConfig?.apiKey;
  const payload = context.payload || context.modalFormData || context.formData || {};

  if (!apiKey) {
    console.error("❌ No API key provided");
    return;
  }

  console.log("📡 Calling API:", apiKey, "with payload:", payload);
  await context.handlers.handleApiCall(apiKey, payload, context.actionConfig);

actions.reloadClassData:
console.log("🔄 Reloading class data");
  await context.handlers.handleApiCall('fitness.classes.api', {});
  console.log("✅ Class data reloaded");

actions.openModal:
const modalName = context.actionParams?.modal || context.actionParams?.modalName;
  if (!modalName) {
    console.error("❌ No modal name provided");
    return;
  }

  console.log("🎭 Opening modal:", modalName);

  context.handlers.setModalFormData({});
  context.handlers.setFieldErrors({});

  context.handlers.setActiveModal(modalName);

  console.log("✅ Modal opened");

actions.closeModal:
console.log("❌ Closing modal");
  context.handlers.setModalFormData({});
  context.handlers.setFieldErrors({});
  context.handlers.setActiveModal(null);
  console.log("✅ Modal closed");

actions.openEditClassModal:
console.log("🔄 Opening edit class modal");
  const itemData = context.actionConfig?.row || context.payload;

  if (!itemData || !itemData._id) {
    console.error("❌ No class data provided");
    return;
  }

  context.handlers.setModalFormData({});
  context.handlers.setFieldErrors({});

  context.handlers.setModalFormData({
    _id: itemData._id,
    className: itemData.className,
    category: itemData.category,
    type: itemData.type,
    price: itemData.price,
    duration: itemData.duration,
    description: itemData.description || '',
    instructor: itemData.instructor || '',
    intensity: itemData.intensity || 'Medium',
    schedule: itemData.schedule || '',
    maxCapacity: itemData.maxCapacity || '',
    equipment: itemData.equipment || []
  });

  context.handlers.setActiveModal('editClass');
  console.log("✅ Edit modal opened");

actions.updateClass:
console.log("🔄 Updating class");
  const formData = context.modalFormData || {};

  if (!formData._id) {
    context.handlers.showNotification({
      type: "toast",
      message: "❌ Class ID missing",
      background: "#E50914"
    });
    return;
  }

  const payload = {
    _id: formData._id,
    className: formData.className,
    category: formData.category,
    type: formData.type,
    price: parseFloat(formData.price),
    duration: formData.duration,
    description: formData.description || '',
    instructor: formData.instructor || '',
    intensity: formData.intensity || 'Medium',
    schedule: formData.schedule || '',
    maxCapacity: parseInt(formData.maxCapacity) || 20,
    equipment: formData.equipment || []
  };

  console.log("🚀 Sending:", payload);
  await context.handlers.handleApiCall('fitness.classes.update', payload);
  console.log("✅ Update completed");

actions.deleteClass:
const itemId = context.row?._id || context.payload?._id;

  if (!itemId) {
    context.handlers.showNotification({
      type: "toast",
      message: "❌ Class ID missing",
      background: "#E50914"
    });
    return;
  }

  if (!confirm('Delete this class? This cannot be undone.')) {
    console.log("🚫 Delete cancelled");
    return;
  }

  console.log("🗑️ Deleting:", itemId);
  await context.handlers.handleApiCall('fitness.classes.delete', { _id: itemId });

actions.searchClasses:
console.log("🔍 Searching classes");
  const filters = context.formData || {};
  const payload = {
    page: 1,
    limit: 10,
    ...filters
  };

  Object.keys(payload).forEach(key => {
    if (payload[key] === '' || payload[key] == null) {
      delete payload[key];
    }
  });

  console.log("🔍 Filters:", payload);
  await context.handlers.handleApiCall('fitness.classes.list', payload);

actions.resetClassFilters:
console.log("🔄 Resetting class filters");
  context.handlers.setFormData({});
  await context.handlers.handleApiCall('fitness.classes.list', { page: 1, limit: 10 });

actions.changeClassPage:
const newPage = context.actionParams?.page || 1;
  const limit = context.actionParams?.limit || 10;
  const currentFilters = context.formData || {};

  const payload = {
    page: newPage,
    limit: limit,
    ...currentFilters
  };

  Object.keys(payload).forEach(key => {
    if (payload[key] === '' || payload[key] == null) {
      delete payload[key];
    }
  });

  console.log("📄 Changing to page:", newPage);
  await context.handlers.handleApiCall('fitness.classes.list', payload);

actions.openReviewModal:
console.log("🎭 Opening review modal");

  context.handlers.setModalFormData({});
  context.handlers.setFieldErrors({});

  context.handlers.setActiveModal("writeReview");

  console.log("✅ Review modal opened");

actions.submitReview:
console.log("📝 Submitting review");

  const formData = context.modalFormData || {};

  console.log("📦 Review form data:", formData);

  const errors = {};

  if (!formData.reviewerName || formData.reviewerName.trim().length < 2) {
    errors.reviewerName = "Name must be at least 2 characters";
  }

  if (!formData.rating || formData.rating < 1 || formData.rating > 5) {
    errors.rating = "Please select a rating (1-5 stars)";
  }

  if (!formData.comment || formData.comment.trim().length < 10) {
    errors.comment = "Review must be at least 10 characters";
  }

  if (Object.keys(errors).length > 0) {
    console.error("❌ Validation errors:", errors);
    context.handlers.setFieldErrors(errors);

    context.handlers.showNotification({
      type: "toast",
      message: "❌ Please fix the errors in the form",
      background: "#E50914",
      duration: 3000
    });

    return;
  }

  context.handlers.setFieldErrors({});

  console.log("🚀 Calling fitness.reviews.submit API");
  await context.handlers.handleApiCall('fitness.reviews.submit', formData);

  console.log("✅ Review submitted successfully");

actions.closeReviewModal:
console.log("❌ Closing review modal");

  context.handlers.setModalFormData({});
  context.handlers.setFieldErrors({});

  context.handlers.setActiveModal(null);

  console.log("✅ Modal closed and data cleared");

actions.handleLogin:
console.log('🔐 Fitness First login action triggered');
const email = context.formData?.email;
const password = context.formData?.password;

if (!email || !password) {
  context.handlers.showNotification({
    type: 'toast',
    message: '❌ Please enter email and password',
    background: '#E50914'
  });
  return;
}

try {
  const response = await fetch('/api/enduser-auth/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',
    body: JSON.stringify({ 
      email, 
      password,
      websiteSlug: 'fitness-first'
    })
  });

  const data = await response.json();

  if (!response.ok) {
    context.handlers.showNotification({
      type: 'toast',
      message: data.error || '❌ Login failed',
      background: '#E50914'
    });
    return;
  }

  console.log('✅ Login successful:', data);
  context.handlers.setData('user', data.user);

  context.handlers.showNotification({
    type: 'toast',
    message: `Welcome back, ${data.user.firstName || 'Athlete'}! 💪`,
    background: '#0072CE'
  });

  setTimeout(() => {
    window.location.href = '/fitness-first/dashboard';
  }, 1000);

} catch (error) {
  console.error('Login error:', error);
  context.handlers.showNotification({
    type: 'toast',
    message: '❌ Network error. Please try again.',
    background: '#E50914'
  });
}

actions.handleSignup:
console.log('📝 Fitness First signup handling');
const { email, password, firstName, lastName, name } = context.formData || {};

if (!email || !password) {
  context.handlers.showNotification({
    type: 'toast',
    message: '❌ Email and password are required',
    background: '#E50914'
  });
  return;
}

try {
  const response = await fetch('/api/enduser-auth/signup', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',
    body: JSON.stringify({
      email: email.trim().toLowerCase(),
      password,
      name: `${firstName?.trim() || ''} ${lastName?.trim() || ''}`.trim(),
      organizationId: '696fd6f8a216cc192d63b84a',
      websiteSlug: 'fitness-first'
    })
  });

  const data = await response.json();

  if (!response.ok) {
    context.handlers.showNotification({
      type: 'toast',
      message: data.error || '❌ Signup failed',
      background: '#E50914',
      duration: 4000
    });
    return;
  }

  console.log('✅ Signup successful:', data);

  context.handlers.showNotification({
    type: 'toast',
    message: '✅ Account created! Welcome to Fitness First.',
    background: '#0072CE',
    duration: 4000
  });

  setTimeout(() => {
    window.location.href = '/fitness-first/login';
  }, 2000);

} catch (error) {
  console.error('❌ Signup error:', error);
  context.handlers.showNotification({
    type: 'toast',
    message: '❌ Network error. Please try again.',
    background: '#E50914'
  });
}

actions.toggleTheme:
const body = document.body;
const isDark = body.classList.contains('dark-mode');

if (isDark) {
  body.classList.remove('dark-mode');
  localStorage.setItem('fitness-theme', 'light');
  console.log('☀️ Light mode activated');
} else {
  body.classList.add('dark-mode');
  localStorage.setItem('fitness-theme', 'dark');
  console.log('🌙 Dark mode activated');
}

actions.loadTheme:
const saved = localStorage.getItem('fitness-theme');
const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

if (saved === 'dark' || (!saved && prefersDark)) {
  document.body.classList.add('dark-mode');
  console.log('🌙 Dark mode loaded');
}

actions.navigateToPage:
const url = context.actionParams?.url;
if (!url) {
  console.error("❌ No URL provided");
  return;
}
console.log("🧭 Navigating to:", url);
window.location.href = url;

actions.clearAuth:
console.log("🚪 Fitness First logout...");

try {
  const response = await fetch('/api/enduser-auth/logout', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',
    body: JSON.stringify({ websiteSlug: 'fitness-first' })
  });

  const data = await response.json();

  if (response.ok) {
    context.handlers.clearAuthData();

    context.handlers.showNotification({
      type: "toast",
      message: "✅ Logged out successfully",
      background: "#0072CE",
      duration: 2000,
    });

    setTimeout(() => {
      window.location.href = data.redirectUrl || '/fitness-first';
    }, 1000);
  }
} catch (error) {
  console.error('Logout error:', error);
  context.handlers.showNotification({
    type: "toast",
    message: "❌ Logout failed",
    background: "#E50914"
  });
}
